public class ClonePair4006 {

    double method1(double x,double y){
      if (x < 0.0) {
        x=-x;
      }
     else   if (x == 0.0) {
        return y < 0.0 ? -y : y;
      }
      if (y < 0.0) {
        y=-y;
      }
     else   if (y == 0.0) {
        return x;
      }
      if (x < y) {
        x/=y;
        return y * Math.sqrt(1.0 + x * x);
      }
      y/=x;
      return x * Math.sqrt(1.0 + y * y);
    }

    double method2(double x,double y){
